# Generated by manage.py generate_test_cases.
from django.http import HttpResponse
from django.urls import resolve

from bloomerp.models.communication.instant_messaging import (
    IMAuthorization,
    IMConnection,
)
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.views.communication.create_im_connection import CreateIMConnectionView


class TestCreateImconnectionView(BloomerpModelViewTestCase):
    """Exercise provider selection, staff access, schema validation and secret persistence."""

    view_name = "add"
    model = IMConnection

    def prepare_configuration(self, scenario: RequestScenario) -> None:
        """Select WhatsApp via the actual first-step endpoint before configuring it."""
        self.client.force_login(self.normal_user)
        response = self.client.post(self.get_endpoint(self.view_name, None), {"provider": "whatsapp"})
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, 'data-wizard-step-index="1"')
        scenario.data = {
            "name": "Support WhatsApp",
            "business_account_id": "123456",
            "phone_number_id": "987654",
            "access_token": "configuration-test-secret",
            "app_secret": "signing-test-secret",
            "webhook_verify_token": "verification-test-secret",
            "provider": "internal",
        }

    def prepare_invalid(self, scenario: RequestScenario) -> None:
        """Ensure errors redisplay without echoing credentials or persisting partial records."""
        self.prepare_configuration(scenario)
        scenario.data["business_account_id"] = "not-an-id"

    def prepare_nonstaff(self, scenario: RequestScenario) -> None:
        """Exercise the explicit staff-only gate independently of model permissions."""
        self.normal_user.is_staff = False
        self.normal_user.save(update_fields=["is_staff"])

    def validate_creation(self, response: HttpResponse) -> bool:
        """Check typed settings and encrypted credentials with a cleared wizard session."""
        connection = IMConnection.objects.get(name="Support WhatsApp")
        authorization = IMAuthorization.objects.get(connection=connection)
        return (
            connection.provider == "whatsapp"
            and connection.status == "draft"
            and connection.external_account_id == "123456"
            and connection.settings
            == {"business_account_id": "123456", "phone_number_id": "987654"}
            and authorization.get_credentials()["access_token"]
            == "configuration-test-secret"
            and "test-secret" not in authorization.credentials
            and "test-secret" not in str(dict(self.client.session))
            and "test-secret" not in response.content.decode()
            and "im_connection_create_wizard" not in self.client.session
        )

    def validate_invalid(self, response: HttpResponse) -> bool:
        """Assert invalid settings neither create a record nor reveal secrets."""
        return (
            not IMConnection.objects.exists()
            and not IMAuthorization.objects.exists()
            and "test-secret" not in response.content.decode()
            and "test-secret" not in str(dict(self.client.session))
        )

    def validate_route(self, response: HttpResponse) -> bool:
        """Confirm the overridden route offers exactly the external provider cards."""
        text = response.content.decode()
        return (
            resolve(self.get_endpoint(self.view_name, None)).func.view_class is CreateIMConnectionView
            and "WhatsApp" in text
            and "Slack" in text
            and 'value="internal"' not in text
            and 'data-wizard-total-steps="2"' in text
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Use declarative generated cases for both wizard steps and access boundaries."""
        return [
            RequestScenario(
                name="Staff without model grants can select providers",
                user=self.normal_user,
                expected=ExpectedResult(response_validators=[self.validate_route]),
            ),
            RequestScenario(
                name="Superuser can select providers",
                user=self.admin_user,
                expected=ExpectedResult(response_validators=[self.validate_route]),
            ),
            RequestScenario(
                name="Cannot skip provider selection",
                user=self.normal_user,
                query_params={"step": "1"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('data-wizard-step-index="0"')
                    ]
                ),
            ),
            RequestScenario(
                name="Internal selection rejected",
                user=self.normal_user,
                method="POST",
                data={"provider": "internal"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Select an external messaging provider.")
                    ]
                ),
            ),
            RequestScenario(
                name="Staff creates encrypted draft",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_configuration,
                expected=ExpectedResult(response_validators=[self.validate_creation]),
            ),
            RequestScenario(
                name="Invalid configuration keeps secrets private",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_invalid,
                expected=ExpectedResult(response_validators=[self.validate_invalid]),
            ),
            RequestScenario(
                name="Nonstaff denied",
                user=self.normal_user,
                prepare=self.prepare_nonstaff,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Anonymous login required",
                expected=ExpectedResult(status_code=302),
            ),
        ]
